"""Component specifications for MC-001..MC-046 (the source for docs/components/*.md).

Each spec is data, consumed by the certification runner for the templated
checks (CHK-001/003/004/005/016/019/020/021/022/023/024).  Invariants name the
exact tests that enforce them; the runner fails the check if a named test is
missing or did not pass.
"""
from __future__ import annotations

BOUNDARY = {
    "spoofing": "Callers authenticate with GAP03-ID/1 Ed25519 credentials; unknown issuer/kid/alg rejected (MC-012).",
    "tampering": "Canonical-JSON digests bind requests/artifacts; hash-chained WAL detects on-disk edits (MC-001/004).",
    "repudiation": "Privileged actions are written to the tamper-evident audit log before commit (MC-013).",
    "disclosure": "Error payloads, logs and explain output are redacted/pseudonymised (MC-014/020/024).",
    "dos": "Size/depth/cardinality bounds on every input; admission + rate limits (MC-001/025).",
    "elevation": "Least-privilege RBAC with two-person rule for high-blast-radius operations (MC-002/017).",
    "replay": "Single-use nonces with bounded cache; idempotency keys return the original outcome (MC-012/026).",
    "stale_state": "Generation / revision / fencing preconditions reject stale decisions (MC-004/005/006).",
    "cross_tenant": "Tenant-scoped reads; reservations of other tenants are never spendable (MC-003/005).",
}
LIBRARY = {k: f"Not applicable at this layer: in-process library without network ingress; {v}" for k, v in {
    "spoofing": "callers are the authenticated service boundary.",
    "tampering": "values are immutable (frozen dataclasses / tuples).",
    "repudiation": "decisions are recorded by the explain store of the caller.",
    "disclosure": "holds no tenant secrets; telemetry passes through privacy.sanitize.",
    "dos": "inputs are bounded by admission limits before reaching it.",
    "elevation": "exposes no privileged operation.",
    "replay": "pure function of its inputs; replay is harmless.",
    "stale_state": "keys/results include generations so stale inputs cannot match.",
    "cross_tenant": "never keys by tenant identity.",
}.items()}


def _i(name, protocol, auth, timeout, retry, failure):
    return {"name": name, "protocol": protocol, "auth": auth, "timeout": timeout, "retry": retry, "failure": failure}


INPROC = ("in-process call", "none (inside service boundary)", "caller deadline", "none", "raises SchedulerError")


def S(mc, title, modules, scope, non_goals, adjacent, interfaces, data_model, invariants, *, threats="boundary",
      threat_overrides=None, authz_na=None, crypto=("Not applicable - holds no keys; integrity via canonical digests.", False),
      sensitive="No tenant secrets; identifiers pseudonymised in telemetry.", fmea=None, concurrency=None, telemetry=(),
      runbook="runbooks/incident-response.md"):
    t = dict(BOUNDARY if threats == "boundary" else LIBRARY)
    t.update(threat_overrides or {})
    return {"mc": mc, "title": title, "modules": list(modules), "scope": scope, "non_goals": non_goals, "adjacent": adjacent,
            "interfaces": interfaces, "data_model": data_model, "invariants": invariants, "threats": t,
            "crypto": {"decision": crypto[0], "requires_external_kms": crypto[1]}, "sensitive": sensitive,
            "fmea": fmea or [], "concurrency": concurrency or "", "telemetry": list(telemetry), "runbook": runbook,
            "authz_na": authz_na}


