BY_MC = {s["mc"]: s for s in SPECS}
STRIDE = tuple(BOUNDARY)


def render(spec: dict) -> str:
    L = [f"# {spec['mc']} — {spec['title']}", "", f"**Modules:** {', '.join('`'+m+'`' for m in spec['modules'])}", "",
         "## Scope", spec["scope"], "", "## Non-goals", spec["non_goals"], "", "## Owned by adjacent services", spec["adjacent"], "",
         "## Interfaces", "", "| Interface | Protocol / version | AuthN/Z | Timeout | Retry | Failure semantics |", "|---|---|---|---|---|---|"]
    L += [f"| {i['name']} | {i['protocol']} | {i['auth']} | {i['timeout']} | {i['retry']} | {i['failure']} |" for i in spec["interfaces"]]
    L += ["", "## Data / state model", spec["data_model"], "", "## Invariants → enforcing tests", ""]
    L += [f"- {t} — `{n}`" for t, n in spec["invariants"]]
    L += ["", "## Threat model (STRIDE + replay / stale-state / cross-tenant)", "", "| Threat | Treatment |", "|---|---|"]
    L += [f"| {k} | {v} |" for k, v in spec["threats"].items()]
    L += ["", "## Cryptography / secrets", spec["crypto"]["decision"] + (" **(production custody blocked: external HSM/KMS)**" if spec["crypto"]["requires_external_kms"] else ""),
          "", "## Sensitive data", spec["sensitive"], "", "## Failure modes", "", "| Failure | Behaviour | Mode |", "|---|---|---|"]
    L += [f"| {a} | {b} | {c} |" for a, b, c in spec["fmea"]]
    L += ["", "## Concurrency / idempotency / retry", spec["concurrency"], "", "## Telemetry", ", ".join(f"`{t}`" for t in spec["telemetry"]) or "via caller",
          "", "## Runbook", f"`{spec['runbook']}`", ""]
    return "\n".join(L)


def write_docs(root: str | None = None) -> list[str]:
    import os
    root = root or os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "docs", "components")
    os.makedirs(root, exist_ok=True)
    out = []
    for s in SPECS:
        p = os.path.join(root, f"{s['mc']}.md")
        with open(p, "w", encoding="utf-8") as fh:
            fh.write(render(s))
        out.append(p)
    return out


if __name__ == "__main__":
    write_docs()
